function loadAssets() {
  return Promise.all(assetPaths.map((path) => new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      assets[path] = img;
      draw();
      resolve();
    };
    img.onerror = () => {
      resolve();
      draw();
    };
    img.src = path;
  })));
}

